
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_k_vjks_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_k_vjks", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([9.433911439664777e+01, 9.066815393754497e+01, 8.564684884411051e+01, 7.892724682864035e+01, 7.021175589367230e+01, 5.939862589618478e+01, 4.679623875217435e+01, 3.332796722883215e+01, 2.052157025190151e+01, 1.010092534359920e+01, 3.870771770334469e+00, 2.498141230206890e+00, 1.913804934078717e+00, 1.264168285662593e+00, 6.079993808847578e-01, 1.474531050484214e-01, -1.488214086088552e-01, -3.332590490386498e-01, -3.592255329353213e-01, -3.445732559612538e-01]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


